// Bring back what was saved, plus the example flight while its switch is on: every event goes through
// a fresh machine again, in time order, with the switches as they were at that moment.
// Nothing from the examples is ever saved.
const EXAMPLE_STATE = { aiWorks: true, doctorOnBoard: false, linkToEarth: true };
const firstPanel = () => {
  const s = INSPIRATION4.subjects.C001;
  return { subject: 'C001', timepoint: 'R+1', analytes: s ? s.panels['R+1'] || [] : [] };
};
// The short example of the main paths, so they are visible at once. Marked as an example in the log.
const EXAMPLE = [
  ['pulse-meter', 72],
  ['bp-meter', { sys: 118, dia: 76 }],
  ['co2-sensor', 2.1],
  ['camera', 'sleeping'],
  ['mood-report', 'fair'],
  ['fitness-test', 30],
  ['inspiration4', firstPanel()],
  ['xray', 'image'],
  ['camera', 'chest_grab_ok'],
  ['camera', 'chest_grab_no_answer'],
];

// With the example flight on, only the paths the flight does not show run here (camera, X-ray,
// real blood tests), so they do not spoil the made-up history.
function mainPathsExample(skipSources) {
  const start = Date.now();
  return EXAMPLE.filter(([id]) => !skipSources.has(id)).map(([sourceId, value], i) => {
    const src = sourceById[sourceId];
    const person = sourceId === 'inspiration4' ? 'i4-c001' : src.section === 'env' ? SHIP.id : CREW[0].id;
    return { v: 1, kind: 'reading', example: true, time: new Date(start + i * 1000).toISOString(), person, state: EXAMPLE_STATE, reading: { source: src.id, indicator: src.indicator, value } };
  });
}

function rebuild() {
  machine = freshMachine();
  log = [];
  counts = {};
  lastByCell = {};
  lastByDest = {};
  const flight = byId('sw-example').checked ? exampleFlight(CREW) : [];
  const paths = stored.length === 0 ? mainPathsExample(new Set(flight.filter((e) => e.reading).map((e) => e.reading.source))) : [];
  const all = [...flight, ...stored, ...paths].sort((a, b) => new Date(a.time) - new Date(b.time));
  replaying = true;
  try {
    for (const ev of all) {
      if (ev.state) machine.setState(ev.state);
      if (ev.kind === 'reading') record(machine.receive({ ...ev.reading, person: ev.person, time: ev.time }), ev.example === true);
      else if (ev.kind === 'review') record(machine.review(ev.person, ev.time), ev.example === true);
    }
  } finally {
    replaying = false;
    machine.setState(readSwitches());
  }
  renderStoreNote();
  renderAll();
}

store = await openStore();
stored = [...store.events];
rebuild();
byId('sw-example').addEventListener('change', rebuild);
byId('hist-indicator').addEventListener('change', renderHistory);
let histFrame = 0;
window.addEventListener('resize', () => {
  cancelAnimationFrame(histFrame);
  histFrame = requestAnimationFrame(renderHistory);
});

// Camera demonstration. The camera code and its models load only when the person switches it on.
// Its events go through send(), exactly like a press of the camera buttons in "Sources".
let camStop = null;
const secs = (s) => `${fmtNum((Math.floor(s * 10) / 10).toFixed(1))} s`;
function renderCamStatus(st) {
  byId('cam-person').textContent = st.person ? 'yes' : 'no';
  const bar = (id, held, need) => {
    const node = byId(id);
    const share = Math.min(1, held / need);
    node.style.width = `${share * 100}%`;
    node.classList.toggle('full', share >= 1);
  };
  byId('cam-chest-val').textContent = secs(st.chestHeld);
  byId('cam-sleep-val').textContent = secs(st.sleepHeld);
  bar('cam-chest-bar', st.chestHeld, CAM_RULES.chestSeconds);
  bar('cam-sleep-bar', st.sleepHeld, CAM_RULES.sleepSeconds);
}
byId('cam-chest-need').textContent = secs(CAM_RULES.chestSeconds);
byId('cam-sleep-need').textContent = secs(CAM_RULES.sleepSeconds);
const CAM_EVENT_TEXT = { chest_grab: 'hand on chest', sleeping: 'person is asleep' };
byId('cam-toggle').addEventListener('click', async () => {
  const btn = byId('cam-toggle');
  if (camStop) {
    camStop();
    camStop = null;
    btn.textContent = 'Turn on the camera';
    byId('cam-off').hidden = false;
    byId('cam-live').hidden = true;
    renderCamStatus({ person: false, chestHeld: 0, sleepHeld: 0 });
    return;
  }
  btn.disabled = true;
  btn.textContent = 'Turning on the camera…';
  byId('cam-last').textContent = 'Loading the models from this computer and asking for camera access.';
  try {
    const { startCamera } = await import('./camera.js');
    camStop = await startCamera({
      video: byId('cam-video'),
      canvas: byId('cam-canvas'),
      onStatus: renderCamStatus,
      onEvent: (kind) => {
        send(sourceById.camera, kind);
        byId('cam-last').textContent = `Camera event: ${CAM_EVENT_TEXT[kind]}. Recorded for: ${personName(selected)}, ${fmtTime(new Date())}. What happened next is in the log.`;
      },
    });
    btn.textContent = 'Turn off the camera';
    byId('cam-off').hidden = true;
    byId('cam-live').hidden = false;
    byId('cam-last').textContent = '';
  } catch (err) {
    camStop = null;
    btn.textContent = 'Turn on the camera';
    const name = err && err.name;
    byId('cam-last').textContent = name === 'NotAllowedError' ? 'Camera access was not allowed, so the camera did not turn on.'
      : name === 'NotFoundError' ? 'No camera found.'
        : `Could not turn on the camera: ${err && err.message ? err.message : err}`;
  } finally {
    btn.disabled = false;
  }
});
